def update(pages):
 for d in pages:
  slug=d['slug']
  if slug in ['best-class/','builds/warlock/','damage-meter/','beginners-guide/','mobile/']:
   d['review_note']='Reviewed 30 October 2026 · Earlier v0.127.0 sections retained; new v0.130.0 checks labelled below · Source-based, not a playtest'
  if slug=='builds/warlock/':
   d['parts'].insert(0,('current-demonology','Current Demonology checks: Dread Lord or Felguard',p('In v0.130.0, Pact of the Nathrezim summons a Dread Lord; its Felseeker inherits Searing Pain upgrades, hits up to six enemies and increases primary-target damage. The inspected text gives a thirty-second base summon interval reduced by cooldown reduction to a thirteen-second floor, with up to two active. Its duration is a runtime rank value, so we do not copy a fixed twenty-second duration from another guide. It is exclusive with Butcher, whose Felguard cleaves and has a stronger low-health target interaction.')+p('Choose the demon branch before drafting the supporting spell. Searing Pain upgrades have an explicit Dread Lord link; they are not proof of an identical Felguard benefit. Earlier Pit Lord recordings describe a different version. This site’s earlier route table below was generic Demonology, not an allocated Pit Lord recipe; its v0.127.0 scope remains stated. No current damage benchmark establishes a winner.')+p('Other current alternatives also exclude each other: Soul Devourer’s Felhunter consumes part of a damage-over-time duration, whereas Soul Link’s Voidwalker scales with damage reduction/bonus health and supplies shielding. Do not combine the benefits of both as if they were one allocated node. '+a('talents/','Check prerequisites and exclusive choices'))))
  if slug=='best-class/':
   d['parts'].insert(0,('current-comparison','First clear and developed ceiling are different questions',table(['Goal','Useful comparison','What this guide can conclude'],[['First clear','How soon defence or damage is available at your actual talent level.','Keep the conditional Warrior/Paladin/Hunter starting choices below; a capstone is not a fresh-character ability.'],['Developed ceiling','Same zone, difficulty, gear, points and boss/wave window.','Not measured here; no numeric or S–D ceiling ordering is justified.'],['Current patch','Changed talent text, such as Warlock demon identities and interactions.','Recheck the affected route before importing an older build.']])+p('This comparison was reviewed against the v0.130.0 menus/text on 30 October. It is deliberately a decision board, not an invented win-rate dataset. Shaman now has a separate '+a('builds/shaman/','current lightning/totem guide')+'; current Warlock changes are explained in its route. Earlier v0.127.0 class recommendations remain scoped below.')))
  if slug=='damage-meter/':
   d['parts'].insert(0,('death-recap','Death Recap: inspect incoming damage before changing DPS',p('Current v0.130.0 client text adds Death Recap with the fatal attacker, overkill, recent incoming damage, absorbed damage, final blows and source breakdown. The avoidable-mechanic share answers a different question from an outgoing DPS meter. We inspected the labels, not a completed death-screen combat test.')+steps(['Read Killed by and the fatal blow first; overkill tells you how far the final hit passed your remaining health.','Inspect recent sources and absorbed damage. A large final hit can arrive after earlier damage left too little health.','Check the avoidable-mechanic share. If positioning dominates the explanation, another damage upgrade alone may not fix the failure.','Change one relevant defensive, movement or damage choice and compare the next similar attempt.'])+p('Absorbed damage is not missing DPS, and a low outgoing total does not prove why the character died. No exact lethal-window duration or source percentage is invented here. '+a('heroic-difficulty/','Check difficulty and healing penalties'))))
  if slug=='beginners-guide/':
   d['parts'].append(('camera','Camera distance and controller zoom',p('The current v0.130.0 Controls text names Max Camera Distance and describes how far the camera may follow behind you. This is a distance limit, not a verified numerical field-of-view setting. The Gamepad panel separately supplies Zoom Speed; bumpers and triggers zoom. If the view is hard to manage, compare distance, follow style and camera speed separately instead of treating them as the same setting.')+p('Open Options → Controls and scroll to the camera controls, then inspect Options → Gamepad for controller settings. We inspected these labels and panels but did not validate a mouse-wheel mapping or physical-controller behaviour; use the current Key Bindings screen to confirm your own binding.')))
  if slug=='mobile/':
   d['parts'].insert(0,('evidence','Compatibility evidence: what each layer proves',table(['Evidence layer','What we checked','What remains open'],[['Original launcher','Current 30 October launcher has coarse-pointer handling and attempts fullscreen/landscape where APIs allow it.','A physical phone’s GPU, touch layout and complete run.'],['Browser capability','WebGPU plus a usable adapter are required.','A browser brand alone does not prove device compatibility.'],['Android Winlator reports','The starsforfeelings thread contains success and startup failures.','A universal GPU driver or preset; reports from one thread are not independent tests.'],['iPhone / iPad','No native app or tested iOS device matrix was established here.','Successful physical-device sessions and persistent save transfer.']])+para('Read 30 October 2026: the mobile thread mixes browser access failures with Windows-under-Winlator experiences. Preserve model, GPU, browser/Winlator version, game build and exact symptom when asking for help. Do not promote a driver suggestion from one reply into a universal fix. '+ref('mobile'))+p('Before importing progress, confirm that this particular route can open menus and select upgrades. '+a('download-platforms/#deck','Steam Deck uses a separate reported route'))))
  if slug=='builds/':
   d['parts']=[(i,t,rewrite_shaman(b)) for i,t,b in d['parts']]
   d['related'].append(('builds/shaman/','Current Shaman checkpoints'))
 return pages+new_pages()

def rewrite_shaman(body):
 import re
 return re.sub(r'<p>[^<]*Shaman[^<]*This first set.*?</p>',p('Shaman now has a current v0.130.0 lightning/totem route. '+a('builds/shaman/','Choose Shaman checkpoints')+' The eight earlier class-route summaries retain their v0.127.0 scope.'),body,flags=re.S)
